#include <vector>
#include <string>

using namespace std;

class Solution {
public:
    vector<string> createGrid(int m, int n) {
        vector<string> grid(m, string(n, '.'));
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (i % 2 == 1 && j < n - 1) {
                    grid[i][j] = '#';
                } else if (i % 2 == 0 && i > 0 && j > 0) {
                    grid[i][j] = '#';
                }
            }
        }
        return grid;
    }
};
